/** Any frame the host writes on `/ws`. */
export type WsServerFrame =
  | WsReply
  | WsEventBatchFrame
  | WsGapFrame
  | WsHeartbeatFrame
  | WsWatchFrame
  | WsCanvasCallFrame
  | WsCanvasLeaseLostFrame
  | WsEvent

/** One terminal of the `terminals` watch. It never carries a claim. */
export type WsTerminalSetEntry = {
  /** A web connection holds a live attachment. */
  attached: boolean
  cwd: string
  projectId: string
  terminalId: string
}

/** One change after the state. */
export type WsWatchDeltaFrame = {
  delta: unknown
  reset?: never
  revision: WsWatchRevision
  scope: string
  state?: never
  type: 'watch'
  watch: WsWatchName
}

/** A watch frame: exactly one of the full state and a delta. */
export type WsWatchFrame = WsWatchStateFrame | WsWatchDeltaFrame

/**
 * A watch a connection can hold. `projects`, `chat_history`, `agents` and
 * `chat_activity` have the empty scope; `fs` and `terminals` are scoped
 * to a project id, `store` to a store key.
 */
export type WsWatchName =
  | 'projects'
  | 'chat_history'
  | 'agents'
  | 'fs'
  | 'store'
  | 'terminals'
  | 'chat_activity'

export const WsWatchNameValues = [
  'projects',
  'chat_history',
  'agents',
  'fs',
  'store',
  'terminals',
  'chat_activity'
] as const

/** `watch` reply payload. */
export type WsWatchReply = {
  revision: WsWatchRevision
  scope: string
  watch: WsWatchName
}

/**
 * Which serve start produced a frame, and its position in the subscription's
 * stream: `n` is `1` for the full state and then rises by one per frame.
 */
export type WsWatchRevision = {
  hostEpoch: string
  n: number
}

/** The full state of a watch. */
export type WsWatchStateFrame = {
  delta?: never
  reset: true
  revision: WsWatchRevision
  scope: string
  state: unknown
  type: 'watch'
  watch: WsWatchName
}
